77	void ASTColumnsApplyTransformer::transform(ASTs & nodes) const
78	{
79	    for (auto & column : nodes)
80	    {
81	        String name;
82	        auto alias = column->tryGetAlias();
83	        if (!alias.empty())
84	            name = alias;
85	        else
86	        {
87	            if (const auto * id = column->as<ASTIdentifier>())
88	                name = id->shortName();
89	            else
90	                name = column->getColumnName();
91	        }
92	        if (lambda)
93	        {
94	            auto body = lambda->as<const ASTFunction &>().arguments->children.at(1)->clone();
95	            std::stack<ASTPtr> stack;
96	            stack.push(body);
97	            while (!stack.empty())
98	            {
99	                auto ast = stack.top();
100	                stack.pop();
101	                for (auto & child : ast->children)
102	                {
103	                    if (auto arg_name = tryGetIdentifierName(child); arg_name && arg_name == lambda_arg)
104	                    {
105	                        child = column->clone();
106	                        continue;
107	                    }
108	                    stack.push(child);
109	                }
110	            }
111	            column = body;
112	        }
113	        else
114	        {
115	            auto function = makeASTFunction(func_name, column);
116	            function->parameters = parameters;
117	            column = function;
118	        }
119	        if (!column_name_prefix.empty())
120	            column->setAlias(column_name_prefix + name);
121	    }
122	}
