15	  *
16	  * These is necessary because identifier with alias can give alias name to any query tree node.
17	  *
18	  * Example:
19	  * WITH (x -> x + 1) AS id, id AS value SELECT value(1);
20	  * In this example id as value is identifier node that has alias, during scope initialization we cannot derive
21	  * that id is actually lambda or expression.
22	  *
23	  * There are no easy solution here, without trying to make full featured expression resolution at this stage.
24	  * Example:
25	  * WITH (x -> x + 1) AS id, id AS id_1, id_1 AS id_2 SELECT id_2(1);
26	  * Example: SELECT a, b AS a, b AS c, 1 AS c;
27	  *
28	  * It is client responsibility after resolving identifier node with alias, make following actions:
29	  * 1. If identifier node was resolved in function scope, remove alias from scope expression map.
30	  * 2. If identifier node was resolved in expression scope, remove alias from scope function map.
31	  *
32	  * That way we separate alias map initialization and expressions resolution.
33	  */
34	class QueryExpressionsAliasVisitor : public InDepthQueryTreeVisitor<QueryExpressionsAliasVisitor>
35	{
36	public:
37	    explicit QueryExpressionsAliasVisitor(ScopeAliases & aliases_)
38	        : aliases(aliases_)
39	    {}
40	
41	    void visitImpl(QueryTreeNodePtr & node)
42	    {
43	        updateAliasesIfNeeded(node);
44	    }
45	
46	    bool needChildVisit(const QueryTreeNodePtr &, const QueryTreeNodePtr & child)
47	    {
48	        if (auto * /*lambda_node*/ _ = child->as<LambdaNode>())
49	        {
50	            updateAliasesIfNeeded(child);
51	            return false;
52	        }
53	        if (auto * query_tree_node = child->as<QueryNode>())
54	        {
55	            if (query_tree_node->isCTE())
56	                return false;
57	
58	            updateAliasesIfNeeded(child);
59	            return false;
60	        }
61	        if (auto * union_node = child->as<UnionNode>())
62	        {
63	            if (union_node->isCTE())
64	                return false;
65	
66	            updateAliasesIfNeeded(child);
67	            return false;
68	        }
69	
70	        return true;
71	    }
