73	    void addDuplicatingAlias(const QueryTreeNodePtr & node)
74	    {
75	        aliases.nodes_with_duplicated_aliases.emplace_back(node);
76	    }
77	
78	    void updateAliasesIfNeeded(const QueryTreeNodePtr & node)
79	    {
80	        if (!node->hasAlias())
81	            return;
82	
83	        auto node_type = node->getNodeType();
84	
85	        // We should not resolve expressions to WindowNode
86	        if (node_type == QueryTreeNodeType::WINDOW)
87	            return;
88	
89	        const auto & alias = node->getAlias();
90	        auto cloned_alias_node = node->clone();
