92	        switch (node_type)
93	        {
94	        case QueryTreeNodeType::LAMBDA:
95	            {
96	                auto [_, inserted] = aliases.alias_name_to_lambda_node.emplace(alias, cloned_alias_node);
97	                if (!inserted || aliases.alias_name_to_expression_node.contains(alias))
98	                    addDuplicatingAlias(cloned_alias_node);
99	                break;
100	            }
101	        case QueryTreeNodeType::IDENTIFIER:
102	            {
103	                auto [_1, inserted_expression] = aliases.alias_name_to_expression_node.emplace(alias, cloned_alias_node);
104	                bool inserted_lambda           = true; // Avoid adding to duplicating aliases if identifier is compound.
105	                bool inserted_table_expression = true; // Avoid adding to duplicating aliases if identifier is compound.
106	
107	                // Alias to compound identifier cannot reference table expression or lambda.
108	                // Example: SELECT x.b as x FROM (SELECT 1 as a, 2 as b) as x
109	                auto * identifier_node = node->as<IdentifierNode>();
110	                if (identifier_node->getIdentifier().isShort())
111	                {
112	                    inserted_lambda = aliases.alias_name_to_lambda_node.emplace(alias, cloned_alias_node).second;
113	                    inserted_table_expression = aliases.alias_name_to_table_expression_node.emplace(alias, cloned_alias_node).second;
114	                }
115	
116	                if (!inserted_expression || !inserted_lambda || !inserted_table_expression)
117	                    addDuplicatingAlias(cloned_alias_node);
118	                break;
119	            }
120	        default:
121	            {
122	                auto [_, inserted] = aliases.alias_name_to_expression_node.emplace(alias, cloned_alias_node);
123	                if (!inserted || aliases.alias_name_to_lambda_node.contains(alias))
124	                    addDuplicatingAlias(cloned_alias_node);
