45	bool RequiredSourceColumnsMatcher::needChildVisit(const ASTPtr & node, const ASTPtr & child)
46	{
47	    if (child->as<ASTSelectQuery>())
48	        return false;
49	
50	    /// Processed. Do not need children.
51	    if (node->as<ASTTableExpression>() || node->as<ASTArrayJoin>() || node->as<ASTSelectQuery>() || node->as<ASTInterpolateElement>())
52	        return false;
53	
54	    if (const auto * f = node->as<ASTFunction>())
55	    {
56	        /// "lambda" visit children itself.
57	        if (f->name == "lambda")
58	            return false;
59	    }
60	
61	    return true;
62	}
