64	void RequiredSourceColumnsMatcher::visit(const ASTPtr & ast, Data & data)
65	{
66	    /// results are columns
67	
68	    if (auto * t = ast->as<ASTIdentifier>())
69	    {
70	        visit(*t, ast, data);
71	        return;
72	    }
73	    if (auto * t = ast->as<ASTFunction>())
74	    {
75	        data.addColumnAliasIfAny(*ast);
76	        visit(*t, ast, data);
77	        return;
78	    }
79	
80	    /// results are tables
81	
82	    if (auto * t = ast->as<ASTTablesInSelectQueryElement>())
83	    {
84	        visit(*t, ast, data);
85	        return;
86	    }
87	
88	    if (auto * t = ast->as<ASTTableExpression>())
89	    {
90	        visit(*t, ast, data);
91	        return;
92	    }
93	
94	    if (auto * t = ast->as<ASTSelectQuery>())
95	    {
96	        visit(*t, ast, data);
97	        return;
98	    }
99	
100	    if (ast->as<ASTSubquery>())
101	    {
102	        return;
103	    }
104	
105	    /// other
106	
107	    if (auto * t = ast->as<ASTArrayJoin>())
