21	  * The exact match of the type is checked. That is, cast to the ancestor will be unsuccessful.
22	  * In the rest, behaves like a dynamic_cast.
23	  */
24	template <typename To, typename From>
25	requires std::is_reference_v<To>
26	To typeid_cast(From & from) noexcept(false)
27	{
28	    if ((typeid(From) == typeid(To)) || (typeid(from) == typeid(To)))
29	        return static_cast<To>(from);
30	
31	    throw DB::Exception(DB::ErrorCodes::LOGICAL_ERROR, "Bad cast from type {} to {}",
32	                        demangle(typeid(from).name()), demangle(typeid(To).name()));
